// One bolt forks into three fixed paths. The volley can damage its target only once.
function voidSniperClip(from,to){let dx=to.x-from.x,dy=to.y-from.y,len=Math.hypot(dx,dy),end={...from};for(let d=6;d<len+6;d+=6){let ratio=Math.min(d,len)/(len||1),q={x:from.x+dx*ratio,y:from.y+dy*ratio};if(!passable(q.x,q.y,6)||!lineClear(end,q,6))return {end,blocked:true};end=q;}return {end,blocked:false};}
function voidSniperPlan(origin,target){let angle=Math.atan2(target.y-origin.y,target.x-origin.x),distance=Math.hypot(target.x-origin.x,target.y-origin.y),along=Math.max(70,Math.min(320,distance-90)),split={x:origin.x+Math.cos(angle)*along,y:origin.y+Math.sin(angle)*along},first=voidSniperClip(origin,split),paths=[];for(let offset of [-Math.PI*25/180,0,Math.PI*25/180]){let points=[{x:origin.x,y:origin.y},{...first.end}];if(!first.blocked)points.push(voidSniperClip(split,{x:split.x+Math.cos(angle+offset)*500,y:split.y+Math.sin(angle+offset)*500}).end);paths.push({points});}return {paths,split:!first.blocked};}
